package ru.neverland.townyelections;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import java.math.BigDecimal;
import org.bukkit.entity.Player;
import com.palmergames.bukkit.towny.TownyAPI;
import ru.neverland.core.*;
import static ru.neverland.townyelections.ElectionPrograms.*;

/** Optional programs journal and cached evidence; election ballots remain owned by the original journal. */
public final class ElectionProgramsService {
    private record Key(UUID town,UUID campaign){}
    private record Cached(Map<String,Object> report,long captured){}
    private final Map<String,String> projectNames;private final NeverLandTownyElections plugin;private final ElectionsService elections;private final ElectionProgramsRepository repository;
    private final Map<UUID,Long> freezing=new LinkedHashMap<>();private volatile Map<Key,Cached> reports=Map.of();private volatile boolean closed;
    private final AtomicReference<Map<Key,Long>> interest=new AtomicReference<>(Map.of());
    public ElectionProgramsService(NeverLandTownyElections plugin,ElectionsService elections,ElectionProgramsRepository repository){this.plugin=plugin;this.elections=elections;this.repository=repository;this.projectNames=names(plugin);}
    private static Map<String,String> names(NeverLandTownyElections plugin){try(var stream=plugin.getResource("program-project-names.yml")){if(stream==null)return Map.of();var yaml=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8));var result=new HashMap<String,String>();for(String id:yaml.getKeys(false))result.put(id,yaml.getString(id,id));return Map.copyOf(result);}catch(Exception error){return Map.of();}}
    private boolean enabled(){return Boolean.TRUE.equals(plugin.getConfig().get("programs.enabled",true));}
    /** Null means wait; bounded waiting prevents this optional journal from indefinitely stalling voting. */
    public String prepareVoting(Election election){
        if(!enabled()||!repository.writable()){freezing.remove(election.id);return "UNAVAILABLE";}
        var state=repository.state();if(state.frozen().containsKey(election.id)){freezing.remove(election.id);return "FROZEN";}
        long now=System.nanoTime();if(freezing.size()>=1024&&!freezing.containsKey(election.id))return "UNAVAILABLE";
        Long began=freezing.get(election.id);if(began==null){began=now;freezing.put(election.id,began);requestAdvance(election.town,election.id,100,true);}
        if(now-began>=5_000_000_000L){freezing.remove(election.id);return "UNAVAILABLE";}
        if(!repository.busy())try{
            var eligible=new HashSet<UUID>();var town=TownyAPI.getInstance().getTown(election.town);
            for(UUID id:election.candidates.keySet()){var draft=state.drafts().get(election.id+"/"+id);if(draft!=null&&Objects.equals(election.candidates.get(id),draft.race())&&ElectionsService.eligible(town,id,"HOLD_OFFICE"))eligible.add(id);}
            repository.commit(state,state.freeze(election.id,election.town,eligible,System.currentTimeMillis())).whenComplete((saved,error)->{
                if(error!=null)plugin.getLogger().warning("Программы не закреплены; выборы продолжатся с явной отметкой недоступности: "+error.getMessage());
                requestAdvance(election.town,election.id,1,false);
            });
        }catch(RuntimeException error){freezing.remove(election.id);return "UNAVAILABLE";}
        return null;
    }
    /** File-writer callbacks only enqueue a global continuation. No Towny access or ledger waiting on that writer. */
    private void requestAdvance(UUID town,UUID campaign,long ticks,boolean timeout){
        if(closed||!plugin.isEnabled()||org.bukkit.Bukkit.isStopping())return;
        try{SuiteScheduler.get().runTaskLater(plugin,()->{
            if(closed)return;invalidate(town);var current=elections.peek(town);
            if(current==null||!current.id.equals(campaign)||current.phase!=Election.Phase.NOMINATION||current.adminPausedAt>0||!current.programsBinding.isEmpty()){freezing.remove(campaign);return;}
            long now=System.currentTimeMillis();if(now<current.nominationEnd){freezing.remove(campaign);return;}
            if(timeout){Long began=freezing.get(campaign);if(began==null)return;long remaining=5_000_000_000L-(System.nanoTime()-began);if(remaining>0){requestAdvance(town,campaign,Math.max(1,(remaining+49_999_999L)/50_000_000L),true);return;}}
            var value=TownyAPI.getInstance().getTown(town);if(value==null){freezing.remove(campaign);return;}
            try{elections.advance(value,now);}catch(Exception|LinkageError error){plugin.getLogger().warning("Переход к голосованию отложен: "+error.getMessage());}
        },ticks);}catch(RuntimeException error){if(!closed&&plugin.isEnabled()&&!org.bukkit.Bukkit.isStopping())plugin.getLogger().warning("Проверка программы будет продолжена обычным циклом выборов: "+error.getMessage());}
    }
    /** Called only after original journal durably binds this exact campaign before voting. */
    public void bound(Election election){if(!election.programsBinding.equals("FROZEN")||!repository.writable()||repository.busy())return;var before=repository.state();var next=before.bind(election.id);if(next!=before)repository.commit(before,next).whenComplete((saved,error)->{if(error!=null)plugin.getLogger().warning("Архив программы ожидает проверки; голоса сохранены");});}
    public CompletionStage<String> edit(Player player,String[] args)throws Exception{try(var guard=SuiteState.guard()){
        if(closed||!enabled()||!repository.writable())throw new IllegalArgumentException("Программы сейчас недоступны; существующие голоса сохранены.");if(!player.hasPermission("townyelections.use")||!player.hasPermission("townyelections.candidate"))throw new IllegalArgumentException("Нет права редактировать программу.");
        var town=ElectionsService.requireTown(player);var election=elections.state(town);long now=System.currentTimeMillis();if(election.phase!=Election.Phase.NOMINATION||now>=election.nominationEnd||election.adminPausedAt>0||!election.programsBinding.isEmpty())throw new IllegalArgumentException("Программу можно менять только во время приёма кандидатов.");
        if(!election.candidates.containsKey(player.getUniqueId())||!ElectionsService.eligible(town,player.getUniqueId(),"HOLD_OFFICE"))throw new IllegalArgumentException("Сначала выдвиньте свою кандидатуру.");var before=repository.state();if(before.frozen().containsKey(election.id))throw new IllegalArgumentException("Программы уже закреплены для голосования.");var old=before.drafts().get(election.id+"/"+player.getUniqueId());var promises=new ArrayList<Promise>(old==null?List.of():old.promises());String statement=old==null?"":old.statement();
        if(args.length<1)throw new IllegalArgumentException("/t elections promise text|building|population|pollution|remove|clear …");String action=args[0].toLowerCase(Locale.ROOT);
        if(action.equals("text")){if(args.length<2)throw new IllegalArgumentException("Добавьте описание программы (до 400 символов).");statement=String.join(" ",Arrays.copyOfRange(args,1,args.length)).replaceAll("(?i)[§&][0-9a-fk-orx]","").strip();if(statement.chars().anyMatch(Character::isISOControl)||statement.contains("§"))throw new IllegalArgumentException("В описании недопустимы управляющие символы.");}
        else if(action.equals("clear")){if(args.length!=1)throw new IllegalArgumentException("/t elections promise clear");statement="";promises.clear();}
        else if(action.equals("remove")){if(args.length!=2)throw new IllegalArgumentException("/t elections promise remove <номер>");int index=Integer.parseInt(args[1])-1;if(index<0||index>=promises.size())throw new IllegalArgumentException("Нет цели с таким номером.");promises.remove(index);}
        else{Kind kind=switch(action){case "building"->Kind.BUILDING;case "population"->Kind.POPULATION;case "pollution"->Kind.POLLUTION;default->throw new IllegalArgumentException("Неизвестная цель: building, population или pollution.");};if(args.length!=(kind==Kind.BUILDING?3:2))throw new IllegalArgumentException(kind==Kind.BUILDING?"/t elections promise building <здание> <уровень 1–5>":"/t elections promise "+action+" <значение>");String project=kind==Kind.BUILDING?args[1]:"";long target=Long.parseLong(args[args.length-1]);var promise=new Promise(kind,project,target,Evidence.unknown("Ожидаются сведения",now));if(kind==Kind.BUILDING){var api=ApiServices.require("NeverLandTownyBuilds","ru.neverland.townybuilds.api.TownyBuildsApi","supportedProjects");try{if(!((Set<?>)api.invoke("supportedProjects",new Class<?>[]{})).contains(project))throw new IllegalArgumentException("Здание не найдено в каталоге.");}catch(ReflectiveOperationException error){throw new IllegalArgumentException("Каталог зданий временно недоступен",error);}}promise=new Promise(kind,project,target,evidence(town.getUUID(),promise,now));String key=promise.key();promises.removeIf(p->p.key().equals(key));promises.add(promise);}
        var current=elections.state(town);long acceptedAt=System.currentTimeMillis();if(!current.id.equals(election.id)||current.phase!=Election.Phase.NOMINATION||current.adminPausedAt>0||acceptedAt>=current.nominationEnd||!current.programsBinding.isEmpty()||!Objects.equals(current.candidates.get(player.getUniqueId()),election.candidates.get(player.getUniqueId()))||!player.hasPermission("townyelections.use")||!player.hasPermission("townyelections.candidate")||!ElectionsService.eligible(town,player.getUniqueId(),"HOLD_OFFICE"))throw new IllegalArgumentException("Условия изменились; программа не сохранена. Откройте меню заново.");
        var next=new Program(election.id,town.getUUID(),player.getUniqueId(),player.getName(),current.candidates.get(player.getUniqueId()),statement,promises,old==null?1:Math.incrementExact(old.revision()),acceptedAt);var stage=repository.commit(before,before.draft(next));stage.whenComplete((saved,error)->requestAdvance(next.town(),next.campaign(),1,false));return stage.thenApply(saved->"Изменение сохранено в журнале. Версию, закреплённую для голосования, смотрите в меню программы.");

    }}
    private Evidence evidence(UUID town,Promise promise,long now){try{
        if(promise.kind()==Kind.BUILDING){var api=ApiServices.require("NeverLandTownyBuilds","ru.neverland.townybuilds.api.TownyBuildsApi","projectLevel","supportedProjects");if(!((Set<?>)api.invoke("supportedProjects",new Class<?>[]{})).contains(promise.project()))return Evidence.unknown("Здание больше не найдено в каталоге",now);Object raw=api.invoke("projectLevel",new Class<?>[]{UUID.class,String.class},town,promise.project());return Evidence.known(integer(raw,0,5),now);}
        if(promise.kind()==Kind.POPULATION){var api=ApiServices.require("NeverLandTownyPopulation","ru.neverland.townypopulation.api.TownyPopulationApi","population");var value=((Optional<?>)api.invoke("population",new Class<?>[]{UUID.class},town)).orElseThrow();if(Boolean.TRUE.equals(value.getClass().getMethod("paused").invoke(value)))return Evidence.unknown("Расчёт населения на паузе",now);return Evidence.known(integer(value.getClass().getMethod("population").invoke(value),0,1_000_000),now);}
        var api=ApiServices.require("NeverLandTownyEnvironment","ru.neverland.townyenvironment.api.TownyEnvironmentApi","environment");var value=(Map<?,?>)api.invoke("environment",new Class<?>[]{UUID.class},town);if(!Boolean.TRUE.equals(value.get("ready"))||Boolean.TRUE.equals(value.get("paused")))return Evidence.unknown("Экологические сведения на паузе",now);var pollution=new BigDecimal(value.get("pollution").toString());if(pollution.signum()<0||pollution.compareTo(BigDecimal.valueOf(100))>0)throw new IllegalArgumentException();return new Evidence(true,pollution.toPlainString(),now,"");
    }catch(ReflectiveOperationException|RuntimeException|LinkageError error){return Evidence.unknown("Подтверждённые сведения временно недоступны",now);}}
    private static long integer(Object value,long min,long max){if(!(value instanceof Number n))throw new IllegalArgumentException();long result=new BigDecimal(n.toString()).longValueExact();if(result<min||result>max)throw new IllegalArgumentException();return result;}
    private void watch(Key key){long now=System.nanoTime();while(true){var old=interest.get();var next=new HashMap<>(old);next.entrySet().removeIf(e->now-e.getValue()>120_000_000_000L);if(next.size()>=128&&!next.containsKey(key)){var oldest=next.entrySet().stream().min(Map.Entry.comparingByValue()).orElseThrow().getKey();next.remove(oldest);}next.put(key,now);if(interest.compareAndSet(old,Map.copyOf(next)))return;}}
    public Map<String,Object> report(UUID town){return report(town,null);}public Map<String,Object> report(UUID town,UUID campaign){if(closed||town==null)return unavailable("Программы временно недоступны");var key=new Key(town,campaign);watch(key);var cached=reports.get(key);return cached==null||System.nanoTime()-cached.captured()>120_000_000_000L?Map.of("available",false,"pending",true,"issue","Сведения готовятся","rows",Map.of()):cached.report();}
    public void refresh(UUID town){refresh(town,null);}public void refresh(UUID town,UUID campaign){try(var guard=SuiteState.guard()){if(closed||town==null)return;var key=new Key(town,campaign);watch(key);capture(key);}}
    public void invalidate(UUID town){var next=new HashMap<>(reports);next.keySet().removeIf(key->key.town().equals(town));reports=Map.copyOf(next);}
    public void tick(){if(closed)return;long now=System.nanoTime();for(var entry:interest.get().entrySet())if(now-entry.getValue()<120_000_000_000L)capture(entry.getKey());}
    private void capture(Key key){var next=new HashMap<>(reports);next.keySet().retainAll(interest.get().keySet());next.put(key,new Cached(buildReport(key),System.nanoTime()));reports=Map.copyOf(next);}
    private Map<String,Object> buildReport(Key key){
        if(!enabled()||!repository.readable())return unavailable("Программы временно отключены или журнал недоступен; выборы продолжают работать");var town=TownyAPI.getInstance().getTown(key.town());if(town==null)return unavailable("Город больше не существует");var current=elections.peek(key.town());var state=repository.state();UUID campaign=key.campaign()==null?(current==null?null:current.id):key.campaign();if(campaign==null)return unavailable("Кампания ещё не создана");boolean same=current!=null&&current.id.equals(campaign);var history=state.frozen().values().stream().filter(f->(f.bound()||current!=null&&current.programReceipts.contains(f.campaign()))&&f.town().equals(key.town())).sorted(Comparator.comparingLong(Frozen::at).reversed()).limit(10).map(f->Map.<String,Object>of("campaign",f.campaign().toString(),"at",f.at())).toList();var frozen=state.frozen().get(campaign);boolean locked=!same||current.phase!=Election.Phase.NOMINATION||frozen!=null;Map<UUID,Program> selected;
        if(same&&current.phase==Election.Phase.NOMINATION&&frozen==null){var draft=new HashMap<UUID,Program>();for(var value:state.drafts().values())if(value.campaign().equals(campaign)&&Objects.equals(current.candidates.get(value.candidate()),value.race()))draft.put(value.candidate(),value);selected=Map.copyOf(draft);}
        else{if(same&&!current.programsBinding.equals("FROZEN")||frozen==null||!frozen.town().equals(key.town())||!same&&!frozen.bound()&&(current==null||!current.programReceipts.contains(campaign)))return Map.of("available",false,"pending",false,"issue","Программы не были закреплены для голосования этой кампании","rows",Map.of(),"history",history);selected=frozen.programs();}
        var evidence=new HashMap<String,Evidence>();var rows=new TreeMap<String,Object>();long now=System.currentTimeMillis();for(var p:selected.values()){var promises=new ArrayList<Map<String,Object>>();for(var promise:p.promises()){var checked=evidence.computeIfAbsent(promise.key(),ignored->evidence(key.town(),promise,now));String status=!checked.known()?"UNKNOWN":promise.met(checked)?(promise.met(promise.baseline())?"ALREADY_MET":"MET"):"PENDING";String title=switch(promise.kind()){case BUILDING->"Завершить здание «"+projectNames.getOrDefault(promise.project(),promise.project())+"»";case POPULATION->"Население города";case POLLUTION->"Загрязнение не выше цели";};promises.add(Map.of("kind",promise.kind().name(),"title",title,"target",Long.toString(promise.target()),"baseline",promise.baseline().known()?promise.baseline().value():"неизвестно","current",checked.known()?checked.value():"неизвестно","status",status,"checkedAt",checked.at(),"issue",checked.issue()));}rows.put(p.candidate().toString(),Map.of("name",p.name(),"race",p.race(),"statement",p.statement(),"revision",p.revision(),"submittedAt",p.submittedAt(),"promises",List.copyOf(promises)));}
        return Map.of("available",true,"pending",false,"issue","","campaign",campaign.toString(),"phase",same?current.phase.name():"ARCHIVE","locked",locked,"rows",Map.copyOf(rows),"history",history);
    }
    private static Map<String,Object> unavailable(String reason){return Map.of("available",false,"pending",false,"issue",reason,"rows",Map.of());}
    public CompletionStage<Void> prepareClose(){closed=true;reports=Map.of();interest.set(Map.of());return repository.prepareClose();}public void awaitClosed(){repository.awaitClosed();}
}
